  1812      u32_to_le(v->pos, x + 12);
  1813      u32_to_le(v->rlen, x + 16);
  1814      float_to_le(v->qual, x + 20);
  1815      u16_to_le(v->n_info, x + 24);
  2930              if ( v->max_unpack && !(v->max_unpack>>1) ) goto end; // BCF_UN_STR
  2931          } else if (i == 6) { // FILTER
