  2977  static inline uint8_t *bcf_unpack_fmt_core1(uint8_t *ptr, int n_sample, bcf_fmt_t *fmt)
  2978  {
  2979      uint8_t *ptr_start = ptr;
  2980      fmt->id = bcf_dec_typed_int1(ptr, &ptr);
  2981      fmt->n = bcf_dec_size(ptr, &ptr, &fmt->type);
  2982      fmt->size = fmt->n << bcf_type_shift[fmt->type];
  2983      fmt->p = ptr;
  2984      fmt->p_off  = ptr - ptr_start;
  2985      fmt->p_free = 0;
  2986      ptr += n_sample * fmt->size;
  2987      fmt->p_len = ptr - fmt->p;
  2988      return ptr;
  2989  }
