  2991  static inline uint8_t *bcf_unpack_info_core1(uint8_t *ptr, bcf_info_t *info)
  2992  {
  2993      uint8_t *ptr_start = ptr;
  2994      info->key = bcf_dec_typed_int1(ptr, &ptr);
  2995      info->len = bcf_dec_size(ptr, &ptr, &info->type);
  2996      info->vptr = ptr;
  2997      info->vptr_off  = ptr - ptr_start;
  2998      info->vptr_free = 0;
  2999      info->v1.i = 0;
  3000      if (info->len == 1) {
  3001          if (info->type == BCF_BT_INT8 || info->type == BCF_BT_CHAR) info->v1.i = *(int8_t*)ptr;
  3002          else if (info->type == BCF_BT_INT32) info->v1.i = le_to_i32(ptr);
  3003          else if (info->type == BCF_BT_FLOAT) info->v1.f = le_to_float(ptr);
  3004          else if (info->type == BCF_BT_INT16) info->v1.i = le_to_i16(ptr);
  3005          else if (info->type == BCF_BT_INT64) info->v1.i = le_to_i64(ptr);
  3006      }
  3007      ptr += info->len << bcf_type_shift[info->type];
  3008      info->vptr_len = ptr - info->vptr;
  3009      return ptr;
  3010  }
