  3082  int vcf_format(const bcf_hdr_t *h, const bcf1_t *v, kstring_t *s)
  3083  {
  3084      int i;
  3085      int32_t max_dt_id = h->n[BCF_DT_ID];
  3086      const char *chrom = bcf_seqname(h, v);
  3087      if (!chrom) {
  3088          hts_log_error("Invalid BCF, CONTIG id=%d not present in the header",
  3089                        v->rid);
  3090          errno = EINVAL;
  3091          return -1;
  3092      }
  3093      bcf_unpack((bcf1_t*)v, BCF_UN_ALL);
  3094      kputs(chrom, s); // CHROM
  3095      kputc('\t', s); kputll(v->pos + 1, s); // POS
  3096      kputc('\t', s); kputs(v->d.id ? v->d.id : ".", s); // ID
  3097      kputc('\t', s); // REF
  3098      if (v->n_allele > 0) kputs(v->d.allele[0], s);
  3099      else kputc('.', s);
  3100      kputc('\t', s); // ALT
  3101      if (v->n_allele > 1) {
  3102          for (i = 1; i < v->n_allele; ++i) {
  3103              if (i > 1) kputc(',', s);
  3104              kputs(v->d.allele[i], s);
  3105          }
  3106      } else kputc('.', s);
  3107      kputc('\t', s); // QUAL
  3108      if ( bcf_float_is_missing(v->qual) ) kputc('.', s); // QUAL
  3109      else kputd(v->qual, s);
  3110      kputc('\t', s); // FILTER
  3111      if (v->d.n_flt) {
  3112          for (i = 0; i < v->d.n_flt; ++i) {
  3113              int32_t idx = v->d.flt[i];
  3114              if (idx < 0 || idx >= max_dt_id
  3115                  || h->id[BCF_DT_ID][idx].key == NULL) {
  3116                  hts_log_error("Invalid BCF, the FILTER tag id=%d at %s:%"PRIhts_pos" not present in the header",
  3117                                idx, bcf_seqname_safe(h, v), v->pos + 1);
  3118                  errno = EINVAL;
  3119                  return -1;
  3120              }
  3121              if (i) kputc(';', s);
  3122              kputs(h->id[BCF_DT_ID][idx].key, s);
  3123          }
  3124      } else kputc('.', s);
  3125      kputc('\t', s); // INFO
  3126      if (v->n_info) {
  3127          int first = 1;
  3128          for (i = 0; i < v->n_info; ++i) {
  3129              bcf_info_t *z = &v->d.info[i];
  3130              if ( !z->vptr ) continue;
  3131              if ( !first ) kputc(';', s);
  3132              first = 0;
  3133              if (z->key < 0 || z->key >= max_dt_id
  3134                  || h->id[BCF_DT_ID][z->key].key == NULL) {
  3135                  hts_log_error("Invalid BCF, the INFO tag id=%d is %s at %s:%"PRIhts_pos,
  3136                                z->key,
  3137                                z->key < 0 ? "negative"
  3138                                : (z->key >= max_dt_id ? "too large" : "not present in the header"),
  3139                                bcf_seqname_safe(h, v), v->pos+1);
  3140                  errno = EINVAL;
  3141                  return -1;
  3142              }
  3143              kputs(h->id[BCF_DT_ID][z->key].key, s);
  3144              if (z->len <= 0) continue;
  3145              kputc('=', s);
  3146              if (z->len == 1)
  3147              {
  3148                  switch (z->type)
  3149                  {
  3150                      case BCF_BT_INT8:  if ( z->v1.i==bcf_int8_missing ) kputc('.', s); else kputw(z->v1.i, s); break;
  3151                      case BCF_BT_INT16: if ( z->v1.i==bcf_int16_missing ) kputc('.', s); else kputw(z->v1.i, s); break;
  3152                      case BCF_BT_INT32: if ( z->v1.i==bcf_int32_missing ) kputc('.', s); else kputw(z->v1.i, s); break;
  3153                      case BCF_BT_INT64: if ( z->v1.i==bcf_int64_missing ) kputc('.', s); else kputll(z->v1.i, s); break;
  3154                      case BCF_BT_FLOAT: if ( bcf_float_is_missing(z->v1.f) ) kputc('.', s); else kputd(z->v1.f, s); break;
  3155                      case BCF_BT_CHAR:  kputc(z->v1.i, s); break;
  3156                      default:
  3157                          hts_log_error("Unexpected type %d at %s:%"PRIhts_pos, z->type, bcf_seqname_safe(h, v), v->pos+1);
  3158                          errno = EINVAL;
  3159                          return -1;
  3160                  }
  3161              }
  3162              else bcf_fmt_array(s, z->len, z->type, z->vptr);
  3163          }
  3164          if ( first ) kputc('.', s);
  3165      } else kputc('.', s);
  3166      // FORMAT and individual information
  3167      if (v->n_sample)
  3168      {
  3169          int i,j;
  3170          if ( v->n_fmt)
  3171          {
  3172              int gt_i = -1;
  3173              bcf_fmt_t *fmt = v->d.fmt;
  3174              int first = 1;
  3175              for (i = 0; i < (int)v->n_fmt; ++i) {
  3176                  if ( !fmt[i].p ) continue;
  3177                  kputc(!first ? ':' : '\t', s); first = 0;
  3178                  if (fmt[i].id < 0 || fmt[i].id >= max_dt_id
  3179                      || h->id[BCF_DT_ID][fmt[i].id].key == NULL) //!bcf_hdr_idinfo_exists(h,BCF_HL_FMT,fmt[i].id) )
  3180                  {
  3181                      hts_log_error("Invalid BCF, the FORMAT tag id=%d at %s:%"PRIhts_pos" not present in the header", fmt[i].id, bcf_seqname_safe(h, v), v->pos+1);
  3182                      errno = EINVAL;
  3183                      return -1;
  3184                  }
  3185                  kputs(h->id[BCF_DT_ID][fmt[i].id].key, s);
  3186                  if (strcmp(h->id[BCF_DT_ID][fmt[i].id].key, "GT") == 0) gt_i = i;
  3187              }
  3188              if ( first ) kputs("\t.", s);
  3189              for (j = 0; j < v->n_sample; ++j) {
  3190                  kputc('\t', s);
  3191                  first = 1;
  3192                  for (i = 0; i < (int)v->n_fmt; ++i) {
  3193                      bcf_fmt_t *f = &fmt[i];
  3194                      if ( !f->p ) continue;
  3195                      if (!first) kputc(':', s);
  3196                      first = 0;
  3197                      if (gt_i == i)
  3198                          bcf_format_gt(f,j,s);
  3199                      else
  3200                          bcf_fmt_array(s, f->n, f->type, f->p + j * (size_t)f->size);
  3201                  }
  3202                  if ( first ) kputc('.', s);
  3203              }
  3204          }
  3205          else
  3206              for (j=0; j<=v->n_sample; j++)
  3207                  kputs("\t.", s);
  3208      }
  3209      kputc('\n', s);
  3210      return 0;
  3211  }
